```verilog
module TopModule (
    input  clk,
    input  areset,
    input  in,
    output out
);

    localparam [1:0] A = 2'd0,
                     B = 2'd1,
                     C = 2'd2,
                     D = 2'd3;

    reg [1:0] state;

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= A;
        end else begin
            case (state)
                A: state <= in ? B : A;
                B: state <= in ? B : C;
                C: state <= in ? D : A;
                D: state <= in ? B : C;
                default: state <= A;
            endcase
        end
    end

    // Moore output: asserted only in state D
    assign out = (state == D);

endmodule
```

**Notes:**
- The state register uses `posedge clk or posedge areset` so the reset is asynchronous and active-high, returning the FSM to state `A`.
- Next-state logic follows the table exactly: A→(A,B), B→(C,B), C→(A,D), D→(C,B).
- The output depends only on the current state (`out = 1` only in state `D`), which makes it a Moore machine.
